import * as THREE from './vendor/three.module.js';
import { getSeabedHeight, getSeabedGridAt } from './seabed.js';
import { seabedGravelBlend } from './seabed-gravel.js';

export const GRAVEL_PEBBLE_COUNT = 12288;
export const GRAVEL_PEBBLE_PATCHES = Object.freeze([{"id":"gravel-carpet-0","x":-4300,"y":-3200,"radius":80,"start":0,"count":384},{"id":"gravel-carpet-1","x":-2450,"y":-4450,"radius":80,"start":384,"count":384},{"id":"gravel-carpet-2","x":-700,"y":-2400,"radius":80,"start":768,"count":384},{"id":"gravel-carpet-3","x":-420,"y":570,"radius":80,"start":1152,"count":384},{"id":"gravel-carpet-4","x":-2700,"y":1900,"radius":80,"start":1536,"count":384},{"id":"gravel-carpet-5","x":-4900,"y":3400,"radius":80,"start":1920,"count":384},{"id":"gravel-carpet-6","x":160,"y":-700,"radius":80,"start":2304,"count":384},{"id":"gravel-carpet-7","x":-1100,"y":-750,"radius":80,"start":2688,"count":384},{"id":"gravel-carpet-8","x":2600,"y":-1700,"radius":80,"start":3072,"count":384},{"id":"gravel-carpet-9","x":3500,"y":-3700,"radius":80,"start":3456,"count":384},{"id":"gravel-carpet-10","x":4500,"y":-6200,"radius":80,"start":3840,"count":384},{"id":"gravel-carpet-11","x":5600,"y":-4300,"radius":80,"start":4224,"count":384},{"id":"gravel-carpet-12","x":6600,"y":-5900,"radius":80,"start":4608,"count":384},{"id":"gravel-carpet-13","x":7500,"y":-3000,"radius":80,"start":4992,"count":384},{"id":"gravel-carpet-14","x":8000,"y":-600,"radius":80,"start":5376,"count":384},{"id":"gravel-carpet-15","x":6200,"y":-2300,"radius":80,"start":5760,"count":384},{"id":"gravel-carpet-16","x":9700,"y":-4200,"radius":80,"start":6144,"count":384},{"id":"gravel-carpet-17","x":10660,"y":-3800,"radius":80,"start":6528,"count":384},{"id":"gravel-carpet-18","x":11090,"y":-5477,"radius":80,"start":6912,"count":384},{"id":"gravel-carpet-19","x":11713,"y":-4613,"radius":80,"start":7296,"count":384},{"id":"gravel-carpet-20","x":12336,"y":-5303,"radius":80,"start":7680,"count":384},{"id":"gravel-carpet-21","x":12800,"y":-3100,"radius":80,"start":8064,"count":384},{"id":"gravel-carpet-22","x":13324,"y":-4711,"radius":80,"start":8448,"count":384},{"id":"gravel-carpet-23","x":13900,"y":-2800,"radius":80,"start":8832,"count":384},{"id":"gravel-carpet-24","x":14500,"y":-4450,"radius":80,"start":9216,"count":384},{"id":"gravel-carpet-25","x":14512,"y":-4511,"radius":80,"start":9600,"count":384},{"id":"gravel-carpet-26","x":15345,"y":-3600,"radius":80,"start":9984,"count":384},{"id":"gravel-carpet-27","x":14938,"y":-5213,"radius":80,"start":10368,"count":384},{"id":"gravel-carpet-28","x":13374,"y":-5681,"radius":80,"start":10752,"count":384},{"id":"gravel-carpet-29","x":11890,"y":-2323,"radius":80,"start":11136,"count":384},{"id":"gravel-carpet-30","x":13143,"y":-1843,"radius":80,"start":11520,"count":384},{"id":"gravel-carpet-31","x":15625,"y":-3900,"radius":80,"start":11904,"count":384}].map(Object.freeze));
// Offline-authored offsets and model styles: signed XY(1/16 map unit), size,
// yaw and squash. Decoding this fixed snapshot never chooses new placements.
const PAYLOAD = '';
let preparedBytes;
function prepared() {
  if (!preparedBytes) {
    const text=atob(PAYLOAD),bytes=new Uint8Array(text.length);
    for(let i=0;i<text.length;i++)bytes[i]=text.charCodeAt(i);
    if(bytes.length!==GRAVEL_PEBBLE_COUNT*7)throw new Error('The authored gravel snapshot has an invalid length.');
    preparedBytes=new DataView(bytes.buffer);
  }
  return preparedBytes;
}

/** Exact physical triangle normal; no smoothing across separate cliff faces. */
function floorNormal(x,y,out) {
  const g=getSeabedGridAt(x,y),column=Math.min(g.columns-2,Math.max(0,Math.floor((x-g.minX)/g.step))),
    row=Math.min(g.rows-2,Math.max(0,Math.floor((y-g.minY)/g.step)));
  const ax=g.minX+column*g.step,ay=g.minY+row*g.step,u=(x-ax)/g.step,v=(y-ay)/g.step;
  const a=getSeabedHeight(ax,ay),b=getSeabedHeight(ax+g.step,ay),c=getSeabedHeight(ax,ay+g.step),d=getSeabedHeight(ax+g.step,ay+g.step);
  const dx=(u+v<=1?b-a:d-c)/g.step,dy=(u+v<=1?c-a:d-b)/g.step;
  return out.set(-dx,1,-dy).normalize();
}

function roundedGeometry() {
  const geometry=new THREE.SphereGeometry(1,10,6),p=geometry.attributes.position;
  let reach=0;
  for(let i=0;i<p.count;i++){
    const x=p.getX(i),y=p.getY(i),z=p.getZ(i),bump=1+.045*Math.sin(x*3.7+z*2.1)*Math.cos(y*3.2);
    p.setXYZ(i,x*bump,y*bump,z*bump);reach=Math.max(reach,Math.hypot(x*bump,y*bump,z*bump));
  }
  // Retain the sphere's smooth radial normals across the shared UV seam.
  geometry.scale(1/reach,1/reach,1/reach);geometry.computeBoundingBox();geometry.computeBoundingSphere();
  geometry.userData={roundedPebble:true,diameterMeters:[.02,.08]};return geometry;
}

/** One close-range decorative draw. All carpets and offsets were authored
 * offline; floor contact/poses are cached once, never regenerated while moving.
 * Mobile uses the same geometry with a smaller nearest-instance cap.
 */
export class GravelPebblesRenderer {
  constructor(_world = {}, { decorateMaterial, mobile = false } = {}) {
    this.group=new THREE.Group();this.group.name='authored-close-gravel-pebbles';this.mobile=mobile;this.disposed=false;
    this.geometry=roundedGeometry();this.material=new THREE.MeshStandardMaterial({color:0x8a8a8a,roughness:.96,metalness:.01});
    this.material.name='loose-rounded-gray-gravel';decorateMaterial?.(this.material);
    this.mesh=new THREE.InstancedMesh(this.geometry,this.material,800);this.mesh.name='nearby-smooth-gravel-pebbles';
    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);this.mesh.receiveShadow=true;this.mesh.castShadow=false;
    this.mesh.setColorAt(0,new THREE.Color(0x727980));this.mesh.instanceColor.setUsage(THREE.DynamicDrawUsage);
    this.mesh.count=0;this.mesh.visible=false;this.group.visible=false;this.group.add(this.mesh);
    this.mesh.boundingSphere=new THREE.Sphere();this.bounds=new THREE.Box3();this.point=new THREE.Vector3();
    this.matrix=new THREE.Matrix4();this.color=new THREE.Color();
    this.positions=new Float32Array(GRAVEL_PEBBLE_COUNT*3);this.normals=new Float32Array(GRAVEL_PEBBLE_COUNT*3);
    this.scales=new Float32Array(GRAVEL_PEBBLE_COUNT*3);this.poses=new Float32Array(GRAVEL_PEBBLE_COUNT*16);
    this.colors=new Float32Array(GRAVEL_PEBBLE_COUNT*3);this.valid=new Uint8Array(GRAVEL_PEBBLE_COUNT);
    this.patchBounds=[];
    this.selection=new Int32Array(800);this.distances=new Float64Array(800);this.limit=800;this.count=0;
    this.lastCamera=new THREE.Vector3(Infinity,Infinity,Infinity);this.lastLimit=0;this.lastRange=0;
    const data=prepared(),normal=new THREE.Vector3(),up=new THREE.Vector3(0,1,0),rotation=new THREE.Quaternion(),yaw=new THREE.Quaternion(),transform=new THREE.Object3D();
    const support=-this.geometry.boundingBox.min.y,palette=[0x484f57,0x565d64,0x626a71,0x6d757d,0x788087,0x858c92,0x5b6269,0x70767c].map(hex=>new THREE.Color(hex));
    for(const patch of GRAVEL_PEBBLE_PATCHES){
      const bounds=new THREE.Box3();this.patchBounds.push(bounds);
      for(let local=0;local<patch.count;local++){
      const index=patch.start+local,offset=index*7,x=patch.x+data.getInt16(offset,true)/16,y=patch.y+data.getInt16(offset+2,true)/16;
      if(seabedGravelBlend(x,y)<.6)continue;
      const diameter=.02+.06*(data.getUint8(offset+4)/255)**1.5,shape=data.getUint8(offset+6);
      const sx=diameter/2,sy=sx*(.30+.28*(shape>>4)/15),sz=sx*(.70+.30*(shape&15)/15);
      floorNormal(x,y,normal);rotation.setFromUnitVectors(up,normal);yaw.setFromAxisAngle(up,data.getUint8(offset+5)/256*Math.PI*2);
      transform.position.set(x/25,getSeabedHeight(x,y)/25,y/25).addScaledVector(normal,sy*support);
      transform.quaternion.copy(rotation).multiply(yaw);transform.scale.set(sx,sy,sz);transform.updateMatrix();
      bounds.expandByPoint(transform.position);
      transform.matrix.toArray(this.poses,index*16);transform.position.toArray(this.positions,index*3);normal.toArray(this.normals,index*3);
      this.scales.set([sx,sy,sz],index*3);palette[(shape+data.getUint8(offset+5))&7].toArray(this.colors,index*3);this.valid[index]=1;
      }
    }
  }

  offer(index,distance) {
    if(this.count<this.limit){
      let child=this.count++;
      while(child>0){const parent=(child-1)>>1;if(this.distances[parent]>=distance)break;
        this.selection[child]=this.selection[parent];this.distances[child]=this.distances[parent];child=parent;}
      this.selection[child]=index;this.distances[child]=distance;return;
    }
    if(distance>=this.distances[0])return;
    let parent=0;
    while(true){let child=parent*2+1;if(child>=this.count)break;
      if(child+1<this.count&&this.distances[child+1]>this.distances[child])child++;
      if(this.distances[child]<=distance)break;
      this.selection[parent]=this.selection[child];this.distances[parent]=this.distances[child];parent=child;}
    this.selection[parent]=index;this.distances[parent]=distance;
  }

  /** @param {THREE.Vector3} camera @param {{mobile?:boolean}} [quality] @param {number} [renderDistance] */
  update(camera,quality,renderDistance=Infinity) {
    if(this.disposed)return;
    const eye=camera?.position??camera;
    if(!eye||!Number.isFinite(eye.x)||!Number.isFinite(eye.y)||!Number.isFinite(eye.z)){
      this.group.visible=this.mesh.visible=false;this.mesh.count=0;this.lastLimit=0;return;
    }
    const range=Math.min(10,Number.isFinite(renderDistance)?Math.max(0,renderDistance):10),limit=(quality?.mobile??this.mobile)?400:800;
    if(this.lastLimit===limit&&this.lastRange===range&&this.lastCamera.distanceToSquared(eye)<.25**2)return;
    this.lastCamera.copy(eye);this.lastLimit=limit;this.lastRange=range;this.limit=limit;this.count=0;
    if(range>0)for(let p=0;p<GRAVEL_PEBBLE_PATCHES.length;p++){
      const patch=GRAVEL_PEBBLE_PATCHES[p],bounds=this.patchBounds[p];
      if(bounds.isEmpty()||bounds.distanceToPoint(eye)>range)continue;
      for(let index=patch.start;index<patch.start+patch.count;index++)if(this.valid[index]){
        const offset=index*3,distance=(eye.x-this.positions[offset])**2+(eye.y-this.positions[offset+1])**2+(eye.z-this.positions[offset+2])**2;
        if(distance<=range*range)this.offer(index,distance);
      }
    }
    this.bounds.makeEmpty();
    for(let slot=0;slot<this.count;slot++){
      const index=this.selection[slot];this.matrix.fromArray(this.poses,index*16);this.mesh.setMatrixAt(slot,this.matrix);
      this.color.fromArray(this.colors,index*3);this.mesh.setColorAt(slot,this.color);
      this.point.fromArray(this.positions,index*3);this.bounds.expandByPoint(this.point);
    }
    this.mesh.count=this.count;this.group.visible=this.mesh.visible=this.count>0;
    this.mesh.instanceMatrix.needsUpdate=true;this.mesh.instanceColor.needsUpdate=true;
    if(this.count){this.bounds.expandByScalar(.041);this.bounds.getBoundingSphere(this.mesh.boundingSphere);}else this.mesh.boundingSphere.makeEmpty();
  }

  dispose() {
    if(this.disposed)return;this.disposed=true;
    this.mesh.dispose();this.geometry.dispose();this.material.dispose();this.group.removeFromParent();this.group.clear();
  }
}
